def estimate(seq):
    """Estimated 2x2 matrix, rows U then D."""
    counts = {'UU': 0, 'UD': 0, 'DU': 0, 'DD': 0}
    for a, b in zip(seq, seq[1:]):
        counts[a + b] += 1
    u = counts['UU'] + counts['UD']
    d = counts['DU'] + counts['DD']
    return [[counts['UU'] / u, counts['UD'] / u],
            [counts['DU'] / d, counts['DD'] / d]]

print(estimate('UUUUUUDDDUUUUUUUUDUU'))
